"""Call-time credential hook infrastructure for outbound MCP / A2A calls.

Credentials for outbound MCP / custom-tool / A2A calls are fetched and
decrypted *only at call time* via a customer-provided hook. The hook receives
an :class:`MCPOutboundCallContext` or :class:`A2AOutboundCallContext` and
returns an :class:`OutboundCallResult` whose ``metadata`` Rasa merges into the
outbound call metadata (MCP ``_meta`` or A2A message metadata).

Nothing in this package persists credentials: hook output is merged into the
outbound request only and is never written to slots, tracker events, Kafka, or
the inspector.
"""

from rasa.shared.agents.outbound_call_hook.context import (
    A2AOutboundCallContext,
    MCPOutboundCallContext,
)
from rasa.shared.agents.outbound_call_hook.hooks import (
    OutboundCallHookError,
    invoke_a2a_call_hook,
    invoke_mcp_call_hook,
    load_call_hook,
    merge_call_metadata,
    validate_hook_result,
    validate_pre_call_hook_import,
)
from rasa.shared.agents.outbound_call_hook.result import OutboundCallResult

__all__ = [
    "A2AOutboundCallContext",
    "MCPOutboundCallContext",
    "OutboundCallHookError",
    "OutboundCallResult",
    "invoke_a2a_call_hook",
    "invoke_mcp_call_hook",
    "load_call_hook",
    "merge_call_metadata",
    "validate_hook_result",
    "validate_pre_call_hook_import",
]
